tape( 'the function returns an object with a `.print()` method for generating a formatted output of results', function test( t ) {
	var table;
	var out;
	var x;
	var y;

	x = [ 1, 2, 3 ];
	y = [ 4, 5, 6 ];

	out = mannWhitneyU( x, y );
	table = out.print();
	t.strictEqual( typeof table, 'string', 'returns a pretty-printed table' );

	out = mannWhitneyU( x, y, {
		'alternative': 'less'
	});
	table = out.print();
	t.strictEqual( typeof table, 'string', 'returns a pretty-printed table' );

	out = mannWhitneyU( x, y, {
		'alternative': 'greater'
	});
	table = out.print();
	t.strictEqual( typeof table, 'string', 'returns a pretty-printed table' );
	t.end();
});

tape( 'the function returns an object with a `.print()` method that accepts a `digits` option to control the number of decimal digits displayed', function test( t ) {
	var table;
	var out;
	var x;
	var y;

	x = [ 1, 2, 3 ];
	y = [ 4, 5, 6 ];

	out = mannWhitneyU( x, y );
	table = out.print({
		'digits': 6
	});
	t.strictEqual( typeof table, 'string', 'returns a pretty-printed table' );
	t.end();
});

tape( 'the function returns an object with a `.print()` method that accepts a `decision` option to control whether the test result should be displayed', function test( t ) {
	var table;
	var out;
	var x;
	var y;

	x = [ 1, 2, 3 ];
	y = [ 4, 5, 6 ];

	out = mannWhitneyU( x, y );
	table = out.print({
		'decision': false
	});
	t.strictEqual( typeof table, 'string', 'returns a pretty-printed table' );
	t.strictEqual( contains( table, 'Test Decision' ), false, 'table does not contain test decision' );
	t.end();
});

